const KW_UI_THEMES=['current','material'];
function normalizeUiTheme(theme){return KW_UI_THEMES.includes(theme)?theme:'current';}
let uiPreferenceRevision=0;
window.applyLiquidGlass=function(){
  var enabled=localStorage.getItem('kw_liquid_glass')==='1';
  var isMaterial=document.documentElement.dataset.kwTheme==='material';
  document.documentElement.dataset.kwLiquidGlass=enabled&&isMaterial?'on':'off';
  if(!(enabled&&isMaterial))document.querySelectorAll('.kw-glass-group-highlight').forEach(function(bubble){bubble.remove();});
  var setting=document.getElementById('liquid-glass-setting');
  if(setting)setting.style.display=isMaterial?'flex':'none';
  var toggle=document.getElementById('liquid-glass-toggle');
  if(toggle){toggle.classList.toggle('active',enabled);toggle.setAttribute('aria-checked',enabled?'true':'false');}
  var label=document.getElementById('liquid-glass-label');
  if(label)label.textContent=enabled?'On':'Off';
  return enabled;
};
window.applyUiTheme=function(theme){
  var selected=normalizeUiTheme(theme||localStorage.getItem('kw_ui_theme'));
  document.documentElement.dataset.kwTheme=selected;
  document.documentElement.style.colorScheme='dark';
  document.querySelectorAll('.ui-theme-option').forEach(function(button){
    var active=button.dataset.theme===selected;
    button.classList.toggle('active',active);
    button.setAttribute('aria-pressed',active?'true':'false');
  });
  var label=document.getElementById('ui-theme-current');
  if(label)label.textContent=selected==='material'?'Material 3 Expressive':selected.charAt(0).toUpperCase()+selected.slice(1);
  window.applyLiquidGlass();
  if(window.applyTopbarSize)window.applyTopbarSize();
  return selected;
};
