const KW_GLASS_INTERACTIVE='button:not(.fav-btn):not(#clear-search):not(#liquid-glass-toggle):not([style*="transform"]),a.btn-primary,a.btn-secondary,a.site-pill,.command-link,.popup-btn,.auth-user-name,.game-card,.product-card,.hire-card';
const KW_GLASS_GROUP='#nav-sidebar,.nav-links,.nav-mobile-drawer';
const KW_GLASS_GROUP_ITEM='.sidebar-link,.nav-links a,.nav-mobile-drawer a';
function updateGlassGroupHighlight(event){
  if(document.documentElement.dataset.kwLiquidGlass!=='on')return;
  var item=event.target instanceof Element?event.target.closest(KW_GLASS_GROUP_ITEM):null;
  var group=item&&item.closest(KW_GLASS_GROUP);
  if(!item||!group)return;
  var bubble=group.querySelector('.kw-glass-group-highlight');
  var first=!bubble;
  if(first){bubble=document.createElement('span');bubble.className='kw-glass-group-highlight';bubble.setAttribute('aria-hidden','true');group.appendChild(bubble);}
  var groupRect=group.getBoundingClientRect();
  var itemRect=item.getBoundingClientRect();
  var scaleX=group.offsetWidth?groupRect.width/group.offsetWidth:1;
  var scaleY=group.offsetHeight?groupRect.height/group.offsetHeight:scaleX;
  if(!Number.isFinite(scaleX)||scaleX<=0)scaleX=1;
  if(!Number.isFinite(scaleY)||scaleY<=0)scaleY=1;
  var x=(itemRect.left-groupRect.left)/scaleX+group.scrollLeft;
  var y=(itemRect.top-groupRect.top)/scaleY+group.scrollTop;
  var radius=getComputedStyle(item).borderRadius||'999px';
  bubble.style.setProperty('--kw-bubble-x',x+'px');
  bubble.style.setProperty('--kw-bubble-y',y+'px');
  bubble.style.setProperty('--kw-bubble-w',(itemRect.width/scaleX)+'px');
  bubble.style.setProperty('--kw-bubble-h',(itemRect.height/scaleY)+'px');
  bubble.style.setProperty('--kw-bubble-radius',radius);
  if(first)requestAnimationFrame(function(){bubble.classList.add('active')});else bubble.classList.add('active');
}
document.addEventListener('pointerover',updateGlassGroupHighlight,{passive:true});
document.addEventListener('pointermove',updateGlassGroupHighlight,{passive:true});
document.addEventListener('pointerout',function(event){
  var group=event.target instanceof Element?event.target.closest(KW_GLASS_GROUP):null;
  if(!group||(event.relatedTarget instanceof Node&&group.contains(event.relatedTarget)))return;
  var bubble=group.querySelector('.kw-glass-group-highlight');
  if(bubble)bubble.classList.remove('active');
},{passive:true});
document.addEventListener('pointermove',function(event){
  if(document.documentElement.dataset.kwLiquidGlass!=='on')return;
  var target=event.target instanceof Element?event.target.closest(KW_GLASS_INTERACTIVE):null;
  if(!target)return;
  var rect=target.getBoundingClientRect();
  var x=event.clientX-rect.left;
  var y=event.clientY-rect.top;
  var nx=Math.max(-1,Math.min(1,(x/Math.max(rect.width,1)-.5)*2));
  var ny=Math.max(-1,Math.min(1,(y/Math.max(rect.height,1)-.5)*2));
  target.style.setProperty('--glass-x',x+'px');
  target.style.setProperty('--glass-y',y+'px');
  target.style.setProperty('--glass-tx',(nx*1.6).toFixed(2)+'px');
  target.style.setProperty('--glass-ty',(ny*1.0).toFixed(2)+'px');
  target.style.setProperty('--glass-rx',(-ny*1.25).toFixed(2)+'deg');
  target.style.setProperty('--glass-ry',(nx*1.55).toFixed(2)+'deg');
},{passive:true});
document.addEventListener('pointerout',function(event){
  var target=event.target instanceof Element?event.target.closest(KW_GLASS_INTERACTIVE):null;
  if(!target||(event.relatedTarget instanceof Node&&target.contains(event.relatedTarget)))return;
  target.style.removeProperty('--glass-x');
  target.style.removeProperty('--glass-y');
  target.style.removeProperty('--glass-tx');
  target.style.removeProperty('--glass-ty');
  target.style.removeProperty('--glass-rx');
  target.style.removeProperty('--glass-ry');
},{passive:true});

function escHtml(s){return(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}

