function setRoleUi(userData){var data=userData||{};var isAdmin=data.admin===true;var isEditor=data.editor===true;var canManage=isAdmin||isEditor;var adminBtn=document.getElementById('admin-popup-btn');var adminSection=document.getElementById('admin-popup-section');var adminPanelBtn=document.getElementById('admin-panel-popup-btn');var approvalsBtn=document.getElementById('approvals-popup-btn');var ordersSection=document.getElementById('orders-popup-section');if(adminBtn)adminBtn.style.display=canManage?'flex':'none';if(adminSection)adminSection.style.display=canManage?'block':'none';if(adminPanelBtn)adminPanelBtn.style.display=isAdmin?'flex':'none';if(approvalsBtn)approvalsBtn.style.display=isAdmin?'flex':'none';if(ordersSection)ordersSection.style.display=shopHasItems?'block':'none';}

window.applySidebarPosition=function(){var pos=localStorage.getItem('kw_sidebar_pos')||'left';if(!['left','right','bottom'].includes(pos))pos='left';document.querySelectorAll('.sidebar-position-option').forEach(function(button){var active=button.dataset.position===pos;button.style.background=active?'var(--primary-dim)':'transparent';button.style.color=active?'var(--primary)':'var(--muted)';button.style.borderColor=active?'var(--primary)':'var(--border)';button.setAttribute('aria-pressed',active?'true':'false');});var side=document.getElementById('nav-sidebar');if(side){side.className='sidebar-'+pos;window.applySidebarSize();}};

window.setSidebarPos=function(position){var pos=['left','right','bottom'].includes(position)?position:'left';localStorage.setItem('kw_sidebar_pos',pos);window.applySidebarPosition();savePrefs();};

window.toggleSidebarPos=function(){var cur=localStorage.getItem('kw_sidebar_pos')||'left';var positions=['left','right','bottom'];window.setSidebarPos(positions[(positions.indexOf(cur)+1)%positions.length]);};

function normalizeSidebarScale(value){var scale=Math.round(Number(value));return Number.isFinite(scale)?Math.max(75,Math.min(175,scale)):100;}
function currentSidebarScale(){var stored=localStorage.getItem('kw_sidebar_scale');if(stored===null){stored=localStorage.getItem('kw_sidebar_size')==='large'?'135':'100';localStorage.setItem('kw_sidebar_scale',stored);}return normalizeSidebarScale(stored);}
window.setSidebarScale=function(value,persist){if(value===''||!Number.isFinite(Number(value)))return;localStorage.setItem('kw_sidebar_scale',String(normalizeSidebarScale(value)));window.applySidebarSize();if(persist!==false)savePrefs();};
window.setSidebarSize=function(size){window.setSidebarScale(size==='large'?135:100,true);};

window.applySidebarSize=function(){var scale=currentSidebarScale();var slider=document.getElementById('sidebar-size-slider');var input=document.getElementById('sidebar-size-percent');if(slider){slider.value=String(scale);slider.style.setProperty('--sidebar-scale-progress',(scale-75)+'%');}if(input)input.value=String(scale);var side=document.getElementById('nav-sidebar');if(!side)return;var pos=localStorage.getItem('kw_sidebar_pos')||'left';var factor=scale/100;var translate=pos==='bottom'?'translateX(-50%)':'translateY(-50%)';side.style.setProperty('transform-origin',pos==='left'?'left center':pos==='right'?'right center':'center bottom','important');side.style.setProperty('transform',translate+' scale('+factor+')','important');if(pos==='bottom')side.style.setProperty('max-width','calc('+(100/factor)+'vw - '+(24/factor)+'px)','important');else side.style.removeProperty('max-width');};

function normalizeTopbarScale(value){var scale=Math.round(Number(value));return Number.isFinite(scale)?Math.max(75,Math.min(175,scale)):100;}
function currentTopbarScale(){return normalizeTopbarScale(localStorage.getItem('kw_topbar_scale')||100);}
window.setTopbarScale=function(value,persist){if(value===''||!Number.isFinite(Number(value)))return;localStorage.setItem('kw_topbar_scale',String(normalizeTopbarScale(value)));window.applyTopbarSize();if(persist!==false)savePrefs();};
window.applyTopbarSize=function(){var scale=currentTopbarScale();var slider=document.getElementById('topbar-size-slider');var input=document.getElementById('topbar-size-percent');if(slider){slider.value=String(scale);slider.style.setProperty('--sidebar-scale-progress',(scale-75)+'%');}if(input)input.value=String(scale);var factor=scale/100;var material=document.documentElement.dataset.kwTheme==='material';var nav=document.querySelector('body>nav');if(nav){nav.style.setProperty('left','50%','important');nav.style.setProperty('right','auto','important');nav.style.setProperty('width',material?'calc('+(100/factor)+'vw - '+(24/factor)+'px)':(100/factor)+'vw','important');nav.style.setProperty('transform-origin','top center','important');nav.style.setProperty('transform','translateX(-50%) scale('+factor+')','important');}var root=document.documentElement;var pageOffset=material?28+64*factor:56*factor;root.style.setProperty('--kw-topbar-current-bottom',(56*factor)+'px');root.style.setProperty('--kw-topbar-material-bottom',(18+64*factor)+'px');root.style.setProperty('--kw-topbar-page-offset',pageOffset+'px');root.style.setProperty('--kw-topbar-popup-top',((material?18:8)+(material?64:56)*factor)+'px');};

window.applySidebarShow=function(){var showMobile=localStorage.getItem('kw_sidebar_show_mobile')!=='0';var showDesktop=localStorage.getItem('kw_sidebar_show_desktop')!=='0';var btns=document.querySelectorAll('.sidebar-show-option');btns.forEach(function(b){var on=b.dataset.device==='mobile'?showMobile:showDesktop;b.style.background=on?'rgba(168,85,247,0.15)':'transparent';b.style.color=on?'var(--primary)':'var(--muted)';b.style.borderColor=on?'var(--primary)':'var(--border)';});var side=document.getElementById('nav-sidebar');if(side){var isMobile=window.matchMedia&&window.matchMedia('(max-width:899px)').matches;var hidden=(isMobile&&!showMobile)||(!isMobile&&!showDesktop);side.style.display=hidden?'none':'';}};

window.toggleSidebarShow=function(device){var key=device==='mobile'?'kw_sidebar_show_mobile':'kw_sidebar_show_desktop';var cur=localStorage.getItem(key)!=='0';localStorage.setItem(key,cur?'0':'1');window.applySidebarShow();savePrefs();};

window.applyGamesNewTabUI=function(){var on=localStorage.getItem('kw_games_newtab')==='1';var lbl=document.getElementById('games-newtab-label');if(lbl)lbl.textContent=on?'On':'Off';};

window.toggleGamesNewTab=function(){var cur=localStorage.getItem('kw_games_newtab')==='1';localStorage.setItem('kw_games_newtab',cur?'0':'1');window.applyGamesNewTabUI();savePrefs();};

window.applyEaglerCloudSaveUI=function(){var on=localStorage.getItem('kw_eagler_cloud_saves')!=='0';var label=document.getElementById('eagler-cloud-save-label');if(label)label.textContent=on?'On':'Off';return on;};
window.toggleEaglerCloudSaves=async function(){var on=localStorage.getItem('kw_eagler_cloud_saves')==='0';localStorage.setItem('kw_eagler_cloud_saves',on?'1':'0');window.applyEaglerCloudSaveUI();var msg=document.getElementById('eagler-cloud-save-msg');if(msg){msg.textContent=auth.currentUser?'Saving…':'Saved on this device.';msg.className='popup-msg ok';}try{await savePrefs(true);if(msg){msg.textContent=on?'Cloud saves enabled. Use the Save Cloud and Load Cloud buttons in Eaglercraft.':'Cloud saves disabled. Local worlds were not removed.';msg.className='popup-msg ok';}}catch(e){if(msg){msg.textContent='Applied here, but account sync failed.';msg.className='popup-msg err';}}};

window.setUiTheme=async function(theme){
  var selected=normalizeUiTheme(theme);
  uiPreferenceRevision++;
  localStorage.setItem('kw_ui_theme',selected);
  window.applyUiTheme(selected);
  var msg=document.getElementById('ui-theme-msg');
  if(msg){msg.textContent=auth.currentUser?'Saving...':'Saved on this device.';msg.className='popup-msg ok';}
  if(!auth.currentUser)return;
  try{
    await savePrefs(true);
    if(msg){msg.textContent='\u2713 Saved to your account.';msg.className='popup-msg ok';}
  }catch(e){
    console.warn('Could not save UI theme to Firestore:',e);
    if(msg){msg.textContent='Applied here, but Firebase sync failed.';msg.className='popup-msg err';}
  }
};

window.toggleLiquidGlass=async function(){
  if(normalizeUiTheme(localStorage.getItem('kw_ui_theme'))!=='material')return;
  var enabled=localStorage.getItem('kw_liquid_glass')!=='1';
  uiPreferenceRevision++;
  localStorage.setItem('kw_liquid_glass',enabled?'1':'0');
  window.applyLiquidGlass();
  var msg=document.getElementById('ui-theme-msg');
  if(msg){msg.textContent=auth.currentUser?'Saving...':'Saved on this device.';msg.className='popup-msg ok';}
  if(!auth.currentUser)return;
  try{
    await savePrefs(true);
    if(msg){msg.textContent='\u2713 Saved to your account.';msg.className='popup-msg ok';}
  }catch(e){
    console.warn('Could not save Liquid glass preference to Firestore:',e);
    if(msg){msg.textContent='Applied here, but Firebase sync failed.';msg.className='popup-msg err';}
  }
};

function savePrefs(throwOnError){var email=auth.currentUser&&auth.currentUser.email;if(!email)return Promise.resolve();var request=setDoc(doc(db,'users',email),{prefs:{sidebarShowMobile:localStorage.getItem('kw_sidebar_show_mobile')!=='0',sidebarShowDesktop:localStorage.getItem('kw_sidebar_show_desktop')!=='0',sidebarPos:['left','right','bottom'].includes(localStorage.getItem('kw_sidebar_pos'))?localStorage.getItem('kw_sidebar_pos'):'left',sidebarScale:currentSidebarScale(),topbarScale:currentTopbarScale(),gamesNewTab:localStorage.getItem('kw_games_newtab')==='1',eaglerCloudSaves:localStorage.getItem('kw_eagler_cloud_saves')!=='0',uiTheme:normalizeUiTheme(localStorage.getItem('kw_ui_theme')),liquidGlass:localStorage.getItem('kw_liquid_glass')==='1'}},{merge:true});return throwOnError?request:request.catch(function(e){console.warn('Could not save prefs to Firestore:',e)});}

async function loadPrefs(){var email=auth.currentUser&&auth.currentUser.email;if(!email)return;var startedAtUiRevision=uiPreferenceRevision;try{var snap=await _kwBootRead(doc(db,'users',email));var data=snap.exists()?snap.data():{};var prefs=data.prefs||{};var m=prefs.sidebarShowMobile;var d=prefs.sidebarShowDesktop;if(typeof m!=='undefined')localStorage.setItem('kw_sidebar_show_mobile',m?'1':'0');if(typeof d!=='undefined')localStorage.setItem('kw_sidebar_show_desktop',d?'1':'0');if(typeof m!=='undefined'||typeof d!=='undefined')window.applySidebarShow();if(['left','right','bottom'].includes(prefs.sidebarPos))localStorage.setItem('kw_sidebar_pos',prefs.sidebarPos);if(Number.isFinite(Number(prefs.sidebarScale)))localStorage.setItem('kw_sidebar_scale',String(normalizeSidebarScale(prefs.sidebarScale)));else if(prefs.sidebarSize==='normal'||prefs.sidebarSize==='large')localStorage.setItem('kw_sidebar_scale',prefs.sidebarSize==='large'?'135':'100');if(Number.isFinite(Number(prefs.topbarScale)))localStorage.setItem('kw_topbar_scale',String(normalizeTopbarScale(prefs.topbarScale)));window.applySidebarPosition();if(typeof prefs.gamesNewTab!=='undefined'){localStorage.setItem('kw_games_newtab',prefs.gamesNewTab?'1':'0');window.applyGamesNewTabUI();}if(typeof prefs.eaglerCloudSaves!=='undefined')localStorage.setItem('kw_eagler_cloud_saves',prefs.eaglerCloudSaves?'1':'0');else if(localStorage.getItem('kw_eagler_cloud_saves')===null)localStorage.setItem('kw_eagler_cloud_saves','1');window.applyEaglerCloudSaveUI();if(startedAtUiRevision===uiPreferenceRevision){if(typeof prefs.liquidGlass!=='undefined')localStorage.setItem('kw_liquid_glass',prefs.liquidGlass?'1':'0');if(prefs.uiTheme==='classic'){localStorage.setItem('kw_ui_theme','current');window.applyUiTheme('current');savePrefs();}else if(KW_UI_THEMES.includes(prefs.uiTheme)){localStorage.setItem('kw_ui_theme',prefs.uiTheme);window.applyUiTheme(prefs.uiTheme);}window.applyLiquidGlass();}window.applySidebarSize();window.applyTopbarSize();}catch(e){console.warn('Could not load prefs from Firestore:',e);}}

window.addEventListener('storage',function(event){
  if(event.key==='kw_ui_theme'){
    uiPreferenceRevision++;
    window.applyUiTheme(event.newValue||'current');
  }else if(event.key==='kw_liquid_glass'){
    uiPreferenceRevision++;
    window.applyLiquidGlass();
  }
});

window.openProfile=async function(userEmail){var modal=document.getElementById('profile-modal');if(!modal)return;var email=userEmail||auth.currentUser?.email;if(!email)return;modal.style.display='flex';try{var snap=await getDoc(doc(db,'users',email));var profileData=snap.exists()?snap.data():{};document.getElementById('profile-username').textContent=profileData.username||email;document.getElementById('profile-fullname').textContent=profileData.fullName||'No name set';document.getElementById('profile-email').textContent=email;document.getElementById('profile-phone').textContent=profileData.phone||'Not set';document.getElementById('profile-bio').textContent=profileData.bio?.replace(/\[newLine\]/g,'\n')||'No bio added yet';var lunchA=profileData.lunchSchedule?.aDay||'';var lunchB=profileData.lunchSchedule?.bDay||'';document.getElementById('profile-lunch-a').textContent=lunchA?lunchA==='1st'?'1st Lunch':'2nd Lunch':'Not set';document.getElementById('profile-lunch-b').textContent=lunchB?lunchB==='1st'?'1st Lunch':'2nd Lunch':'Not set';var pfpUrl=profileData.pfp||'';var avatarEl=document.getElementById('profile-avatar-large');if(pfpUrl){avatarEl.innerHTML='<img src="'+pfpUrl+'" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:50%;">';avatarEl.style.fontSize='';}else{avatarEl.textContent=(profileData.username||email)[0].toUpperCase();avatarEl.style.fontSize='2rem';}var banner=document.getElementById('profile-banner');if(banner){if(profileData.bannerImg){banner.style.background='';banner.style.backgroundImage='url(\''+profileData.bannerImg+'\')';banner.style.backgroundSize='cover';banner.style.backgroundPosition='center';}else if(profileData.bannerColor){banner.style.backgroundImage='';banner.style.background=profileData.bannerColor;}else{banner.style.backgroundImage='';banner.style.background='linear-gradient(135deg,rgba(168,85,247,0.15),rgba(34,211,238,0.15))';}}var editBtn=document.getElementById('profile-edit-btn');if(editBtn)editBtn.style.display=(email===auth.currentUser?.email)?'block':'none';try{var userSnap=await getDoc(doc(db,'users',email));var ud=userSnap.exists()?userSnap.data():{};var isActive=ud.active!==false;var isAdmin=ud.admin===true;var isEditor=ud.editor===true;var isOrders=ud.orders===true;var jobTag=String(ud.jobTag||'').trim();var pills='<span class="role-pill '+(isActive?'active':'inactive')+'">'+(isActive?'\u2713 Active':'\u2717 BANNED')+'</span>';if(isAdmin)pills+='<span class="role-pill admin">\u2B61 Admin</span>';if(isEditor)pills+='<span class="role-pill editor">\u270E Editor</span>';if(isOrders)pills+='<span class="role-pill orders">\uD83D\uDCE6 Orders</span>';if(jobTag)pills+='<span class="role-pill job">'+escHtml(jobTag)+'</span>';var rolesEl=document.getElementById('profile-roles');var rolesRow=document.getElementById('profile-roles-row');if(rolesEl)rolesEl.innerHTML=pills;if(rolesRow)rolesRow.style.display='block';}catch(e){}}catch(e){console.error('Error opening profile:',e);}};window.closeProfile=function(){var modal=document.getElementById('profile-modal');if(modal)modal.style.display='none';};

var _openProfileBase=window.openProfile;window.openProfile=async function(userEmail){await _openProfileBase(userEmail);var email=userEmail||auth.currentUser?.email;var btn=document.getElementById('profile-message-btn');if(!btn)return;var isOther=!!email&&email!==auth.currentUser?.email;btn.style.display=isOther?'block':'none';btn.dataset.email=email||'';btn.dataset.username=document.getElementById('profile-username')?.textContent||email||'';};

document.addEventListener('click',function(e){var popupEl=document.getElementById('user-popup');var badge=document.getElementById('nav-user-badge');if(popupEl&&popupEl.classList.contains('open')&&badge&&!badge.contains(e.target)&&!popupEl.contains(e.target)){popupEl.classList.remove('open')}});

onAuthStateChanged(auth,async function(user){var badge=document.getElementById('nav-user-badge');if(user){loadPrefs();try{var activeSnap=await getDoc(doc(db,'users',user.email));var activeData=activeSnap.exists()?activeSnap.data():null;if(activeData&&activeData.active===false){await signOut(auth);return;}}catch(e){}try{var snap=await getDoc(doc(db,'users',user.email));var data=snap.exists()?snap.data():{};var username=data.username||user.email;var fullName=data.fullName||'';var pfpUrl=data.pfp||'';window.renderUserBadge(username,pfpUrl);window.renderUserPopupHeader(username,user.email,fullName,pfpUrl);}catch(e){window.renderUserBadge(user.displayName||user.email,'');window.renderUserPopupHeader(user.displayName||user.email,user.email,'','');}try{var contentSnap=await getDoc(doc(db,'siteContent','main'));if(contentSnap.exists()){var contentData=contentSnap.data();shopHasItems=Array.isArray(contentData.shop)&&contentData.shop.length>0;if(typeof window.populatePage==='function')window.populatePage(contentData);if(typeof window.kwMaybeShowNoticePopup==='function')window.kwMaybeShowNoticePopup(contentData.noticePopup);}}catch(e){}try{var userSnap=await getDoc(doc(db,'users',user.email));var userData=userSnap.exists()?userSnap.data():{};setRoleUi(userData);}catch(e){}}else{if(badge)badge.innerHTML='';document.getElementById('popup-display-name').textContent='';document.getElementById('popup-email').textContent='';document.getElementById('popup-avatar').textContent='?';document.getElementById('profile-modal').style.display='none';document.getElementById('settings-modal').style.display='none';setRoleUi(null);}});applySidebarPosition();applySidebarSize();applyTopbarSize();applySidebarShow();window.applyEaglerCloudSaveUI();window.addEventListener('resize',function(){window.applySidebarShow();window.applySidebarSize();window.applyTopbarSize();});

// -- Notice popup (admin-set, shown on page load) --
function kwNoticeHash(str){var h=5381;for(var i=0;i<str.length;i++){h=((h<<5)+h)^str.charCodeAt(i);}return 'kwn'+(h>>>0).toString(36);}
window.kwMaybeShowNoticePopup=function(np){
  if(!np||np.enabled!==true)return;
  var title=(np.title||'').trim();
  var text=(np.text||'').trim();
  if(!title&&!text)return;
  // The broadcast id changes only when an admin explicitly chooses
  // "Show to everyone again". Editing/saving copy no longer replays it.
  var hash=String(np.broadcastId||kwNoticeHash(title+'\n'+text));
  var storeKey='kw_notice_popup_seen';
  var remember=np.remember!==false;
  if(remember){try{if(localStorage.getItem(storeKey)===hash)return;}catch(e){}}
  var modal=document.getElementById('notice-popup-modal');
  if(!modal){
    modal=document.createElement('div');
    modal.id='notice-popup-modal';
    modal.style.cssText='display:none;position:fixed;inset:0;z-index:10090;background:rgba(0,0,0,0.72);backdrop-filter:blur(3px);align-items:center;justify-content:center;padding:1rem;';
    modal.innerHTML='<div style="background:var(--card);border:1px solid rgba(239,68,68,0.35);border-radius:12px;width:100%;max-width:520px;box-shadow:0 20px 60px rgba(0,0,0,0.8),0 0 40px rgba(239,68,68,0.12);overflow:hidden;"><div style="padding:1.4rem 1.6rem 1.5rem;"><div style="display:flex;align-items:center;gap:0.6rem;margin-bottom:0.7rem;"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#ef4444" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" x2="12" y1="9" y2="13"/><line x1="12" x2="12.01" y1="17" y2="17"/></svg><h3 id="notice-popup-title" style="font-family:var(--font-display);font-size:0.78rem;letter-spacing:0.15em;text-transform:uppercase;color:#ef4444;margin:0;"></h3></div><div id="notice-popup-text" style="color:rgba(226,232,240,0.9);font-size:0.9rem;line-height:1.65;"></div><button id="notice-popup-dismiss" style="margin-top:1.25rem;padding:0.6rem 1.6rem;background:var(--primary);color:#fff;border:none;border-radius:6px;font-family:var(--font-display);font-size:0.62rem;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;cursor:pointer;">Got it</button></div></div>';
    document.body.appendChild(modal);
    modal.addEventListener('click',function(e){if(e.target===modal)window.kwDismissNoticePopup();});
    document.getElementById('notice-popup-dismiss').addEventListener('click',function(){window.kwDismissNoticePopup();});
  }
  var t=document.getElementById('notice-popup-title');
  if(t)t.textContent=title;
  var x=document.getElementById('notice-popup-text');
  if(x)x.innerHTML=text;
  window.__kwNoticePopupHash=hash;
  window.__kwNoticePopupRemember=remember;
  modal.style.display='flex';
};
window.kwDismissNoticePopup=function(){
  var modal=document.getElementById('notice-popup-modal');
  if(modal)modal.style.display='none';
  try{if(window.__kwNoticePopupHash&&window.__kwNoticePopupRemember!==false)localStorage.setItem('kw_notice_popup_seen',window.__kwNoticePopupHash);}catch(e){}
};

(function(){
  const account=document.querySelector('#settings-modal [data-tab="account"].settings-tab-content');
  if(!account)return;
  const label=document.createElement('label');label.style.cssText='display:flex;gap:.6rem;align-items:center;margin-top:1rem;color:var(--text);font-size:.8rem';
  const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=localStorage.getItem('kw_ai_show_usage')!=='0';
  checkbox.onchange=()=>{localStorage.setItem('kw_ai_show_usage',checkbox.checked?'1':'0');window.dispatchEvent(new Event('kw-ai-usage-preference'));};
  label.append(checkbox,document.createTextNode('Show AI message usage'));account.appendChild(label);
})();
